// Builders for the schemaVersion 2 motion/lean fixtures. The fixtures under
// testdata/contracts/motion-lean/v2 are generated by build-v2-fixtures.mjs from
// these helpers (and checked for drift by the test runner), so a contract change
// is made in one place. Nothing here validates: the validator is the judge.

import { createHash } from 'node:crypto';

export const T0 = 1_000_000_000; // monotonic microseconds of the first sample
const BOOT_ANCHOR_MS = 1_791_000_000_000;

export const utcOf = (us) => new Date(BOOT_ANCHOR_MS + (us - 0) / 1000).toISOString();
export const sha256 = (data) => createHash('sha256').update(data).digest('hex');

export function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value !== null && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(value[k])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

export const POLICY = { kind: 'time_bucket_first', periodUs: 20000, policyVersion: 'tbf-1', lossy: true, verifiedAnchorRule: 'first_verified_measurement', unverifiedRule: 'received_time_bucket' };

const SENSOR_VALUES = {
  accelerometer: () => ({ xMps2: 0.1, yMps2: 0.2, zMps2: 9.8 }),
  gyroscope: () => ({ xRadPerS: 0.01, yRadPerS: 0.0, zRadPerS: -0.01 }),
  attitude: () => ({ qw: 1, qx: 0, qy: 0, qz: 0 }),
};

export function source(sourceId, sensorType, o = {}) {
  const bucket = o.policy === true;
  const declaration = {
    sourceId,
    sensorType,
    platformFused: sensorType === 'attitude',
    available: true,
    measurementClock: o.clock ?? 'elapsed_realtime',
    axisFrame: 'android_sensor',
    requestedSamplingPeriodUs: 20000,
    maxReportLatencyUs: 0,
    storageStride: bucket ? null : 1,
    gapThresholdUs: 100000,
  };
  if (sensorType === 'attitude') declaration.attitudeReference = 'game_rotation_vector';
  if (bucket) declaration.inputPolicy = { ...POLICY, ...(o.policyOverride ?? {}) };
  return { ...declaration, ...(o.override ?? {}) };
}

export const ACC = 'android-accelerometer';
export const GYR = 'android-gyroscope';

// ------------------------------------------------------------------ motion

export class MotionLog {
  constructor({ rec = 'r-v2-motion', boot = 'boot-a', version = 2 } = {}) {
    this.rec = rec;
    this.boot = boot;
    this.version = version;
    this.lines = [];
    this.ctl = 0;
    this.seq = new Map();
    this.types = new Map();
    this.clock = new Map();
    this.samples = new Map(); // `${sourceId}#${sequence}` -> {t, controlSeqBefore}
    this.now = T0 - 100000;
  }

  push(obj) {
    this.lines.push(typeof obj === 'string' ? obj : JSON.stringify(obj));
    return this;
  }

  lastSequences() {
    const map = {};
    for (const id of this.types.keys()) map[id] = (this.seq.get(id) ?? 0) - 1;
    return map;
  }

  event(eventType, fields = {}, o = {}) {
    const at = o.at ?? this.now;
    const record = {
      schemaVersion: this.version,
      recordType: 'motion_event',
      eventType,
      recordingId: this.rec,
      deviceBootId: o.boot ?? this.boot,
      occurredAtUtc: utcOf(at),
      occurredMonotonicUs: at,
      lastSequences: o.lastSequences ?? this.lastSequences(),
      ...(this.version === 2 ? { controlSequence: o.cs ?? this.ctl } : {}),
      ...fields,
    };
    if (o.cs === undefined) this.ctl += 1;
    else this.ctl = o.cs + 1;
    return this.push(record);
  }

  started(sources, o = {}) {
    for (const s of sources) {
      this.types.set(s.sourceId, s.sensorType);
      this.clock.set(s.sourceId, s.measurementClock);
    }
    return this.event('motion_started', { platform: 'android', appVersion: '0.2.0+fixture', bootAnchorUtcMs: BOOT_ANCHOR_MS, sources }, o);
  }

  clockMap(mapId = 0, o = {}) {
    return this.event('clock_map', { mapId, effectiveFromMonotonicUs: o.from ?? T0 - 100000, offsetUtcMinusMonotonicUs: BOOT_ANCHOR_MS * 1000, mappingSource: 'wall_clock_pair', uncertaintyUs: 1500 }, o);
  }

  sample(sourceId, t, o = {}) {
    const sequence = o.sequence ?? this.seq.get(sourceId) ?? 0;
    const measurement = o.measured === undefined ? (this.clock.get(sourceId) === 'elapsed_realtime' ? t : null) : o.measured;
    const accuracy = o.accuracy === undefined ? 'high' : o.accuracy;
    const clockMapId = o.clockMapId === undefined ? (measurement === null ? null : 0) : o.clockMapId;
    const flags = [...(o.flags ?? [])];
    if (measurement === null) flags.push('measurement_monotonic_unavailable');
    if (accuracy === null) flags.push('accuracy_unavailable');
    if (clockMapId === null) flags.push('clock_map_unavailable');
    const received = o.received ?? t + 1500;
    const record = {
      schemaVersion: this.version,
      recordType: 'motion_sample',
      recordingId: this.rec,
      sourceId,
      sensorType: this.types.get(sourceId),
      deviceBootId: o.boot ?? this.boot,
      sequence,
      measurementMonotonicUs: measurement,
      receivedMonotonicUs: received,
      receivedAtUtc: utcOf(received),
      clockMapId,
      accuracyLevel: accuracy,
      qualityFlags: flags,
      ...SENSOR_VALUES[this.types.get(sourceId)](),
      ...(o.fields ?? {}),
    };
    this.samples.set(`${sourceId}#${sequence}`, { t: measurement, controlSeqBefore: this.ctl - 1 });
    this.seq.set(sourceId, Math.max(this.seq.get(sourceId) ?? 0, sequence + 1));
    this.now = Math.max(this.now, received);
    return this.push(record);
  }

  // Convenience: a run of samples every `step` microseconds.
  samples_(sourceId, from, count, step = 20000, o = {}) {
    for (let i = 0; i < count; i += 1) this.sample(sourceId, from + i * step, o);
    return this;
  }

  anchor(sourceId, o = {}) {
    return this.event('selection_anchor', { sourceId, policyVersion: 'tbf-1', timeBase: o.timeBase ?? 'measurement', anchorUs: o.anchorUs ?? T0, reason: o.reason ?? 'start' }, o);
  }

  accuracyState(sourceId, previous, next, o = {}) {
    return this.event('source_accuracy_state', { sourceId, previousAccuracyState: previous, accuracyState: next, atMeasurementMonotonicUs: o.atMeasurement ?? null, atReceivedMonotonicUs: o.atReceived ?? this.now, reason: o.reason ?? 'accuracy_callback' }, o);
  }

  stats(sourceId, f, o = {}) {
    const complete = f.complete ?? true;
    const record = {
      sourceId,
      policyVersion: 'tbf-1',
      windowIndex: f.windowIndex ?? 0,
      closeReason: f.closeReason ?? 'periodic',
      firstKeptSequence: f.first ?? null,
      lastKeptSequence: f.last ?? null,
      keptCount: f.kept ?? 0,
      receivedCount: complete ? f.received ?? 0 : null,
      skippedIntentionalCount: complete ? f.skipped ?? 0 : null,
      invalidCount: complete ? f.invalid ?? 0 : null,
      nonmonotonicCount: complete ? f.nonmono ?? 0 : null,
      bufferDroppedCount: complete ? f.dropped ?? 0 : null,
      pendingIn: complete ? f.pendingIn ?? 0 : null,
      pendingOut: complete ? f.pendingOut ?? 0 : null,
      observedAccuracyTransitions: f.obs === undefined ? (complete ? 0 : null) : f.obs,
      complete,
    };
    return this.event('selection_stats', record, o);
  }

  dropped(sourceId, count, reason = 'buffer_full', o = {}) {
    return this.event('samples_dropped', { sourceId, droppedCount: count, firstDroppedMonotonicUs: o.first ?? null, lastDroppedMonotonicUs: o.last ?? null, reason }, o);
  }

  sourceClock(sourceId, previous, next, reason = 'verification_passed', o = {}) {
    this.clock.set(sourceId, next);
    return this.event('source_clock_state', { sourceId, previousMeasurementClock: previous, measurementClock: next, reason }, o);
  }

  resumed(reason = 'process_restart', o = {}) {
    return this.event('recording_resumed', { reason, resumedSequences: o.resumedSequences ?? Object.fromEntries([...this.types.keys()].map((id) => [id, this.seq.get(id) ?? 0])) }, o);
  }

  truncated(resumedSequences, o = {}) {
    return this.event('log_truncated', { truncatedBytes: 77, resumedSequences }, o);
  }

  clockAdjusted(o = {}) {
    return this.event('clock_adjusted', { previousDeviceBootId: o.previousBoot ?? this.boot, previousBootAnchorUtcMs: BOOT_ANCHOR_MS, bootAnchorUtcMs: BOOT_ANCHOR_MS + 4000, thresholdMs: 500 }, o);
  }

  edit(index, fn) {
    const record = JSON.parse(this.lines[index]);
    fn(record);
    this.lines[index] = JSON.stringify(record);
    return this;
  }

  text() {
    return `${this.lines.join('\n')}\n`;
  }
}

// ------------------------------------------------------------------ lean

export const EXTREMUM_POLICY = { policyVersion: 'extremum-min-abs-100ms-1', rule: 'min_abs_in_same_side_window', minWindowUs: 100000 };
export const QUALIFIED_CONFIG = (inputs = [{ sourceId: ACC, sensorType: 'accelerometer', inputPolicy: POLICY, storageStride: null }]) => ({
  algorithmVersion: 'lean-geometry-2',
  extremumPolicy: EXTREMUM_POLICY,
  autoReferenceConfigFingerprint: null,
  inputs,
  estimatorOutputPeriodUs: 50000,
  applicability: { platform: 'android', sensorProfileId: 'sensor-profile-fixture', mountProfileId: 'mount-profile-fixture' },
});

export class LeanLog {
  constructor({ rec = 'r-v2-lean', run = 'run-1', boot = 'boot-a', version = 2 } = {}) {
    this.rec = rec;
    this.run = run;
    this.boot = boot;
    this.version = version;
    this.lines = [];
    this.seq = new Map();
    this.now = T0;
    this.epoch = -1;
  }

  push(obj) {
    this.lines.push(typeof obj === 'string' ? obj : JSON.stringify(obj));
    return this;
  }

  lastSequences() {
    return Object.fromEntries([...this.seq.entries()].map(([id, next]) => [id, next - 1]));
  }

  event(eventType, fields = {}, o = {}) {
    const at = o.at ?? this.now;
    return this.push({
      schemaVersion: this.version,
      recordType: 'lean_event',
      eventType,
      recordingId: this.rec,
      leanRunId: o.run ?? this.run,
      sourceId: 'lean-estimator',
      deviceBootId: o.boot ?? this.boot,
      occurredAtUtc: utcOf(at),
      occurredMonotonicUs: at,
      lastSequences: o.lastSequences ?? this.lastSequences(),
      ...fields,
    });
  }

  record(recordType, sourceId, fields, o = {}) {
    const sequence = o.sequence ?? this.seq.get(sourceId) ?? 0;
    this.seq.set(sourceId, Math.max(this.seq.get(sourceId) ?? 0, sequence + 1));
    return this.push({
      schemaVersion: this.version,
      recordType,
      recordingId: this.rec,
      leanRunId: o.run ?? this.run,
      sourceId,
      deviceBootId: o.boot ?? this.boot,
      sequence,
      qualityFlags: o.flags ?? [],
      ...fields,
    });
  }

  started(o = {}) {
    const q = o.qualification ?? { status: 'experimental', qualificationRef: null, qualifiedConfiguration: null, configurationFingerprint: null };
    return this.event('lean_started', {
      platform: 'android',
      appVersion: '0.2.0+fixture',
      algorithmVersion: o.algorithmVersion ?? 'lean-geometry-2',
      inputSources: o.inputSources ?? [{ sourceId: ACC, stream: 'motion' }],
      inputConsumption: 'stored_only',
      maxInputGapUs: 100000,
      replayable: o.replayable ?? false,
      replayScope: o.replayScope ?? { estimate: o.replayable ?? false, calibration: false, refilter: false },
      extremumPolicy: o.extremumPolicy ?? EXTREMUM_POLICY,
      autoReferenceConfigFingerprint: o.autoFp ?? null,
      qualification: q,
      derivesFrom: o.derivesFrom ?? null,
    }, o);
  }

  qualified(config = QUALIFIED_CONFIG(), o = {}) {
    return {
      status: 'qualified',
      qualificationRef: o.ref === undefined ? 'qual-local-0001' : o.ref,
      qualifiedConfiguration: config,
      configurationFingerprint: o.fingerprint ?? sha256(canonicalJson(config)),
    };
  }

  reset(initialInputs = [{ sourceId: ACC, firstSequence: 0 }], o = {}) {
    this.epoch += 1;
    return this.event('estimator_reset', { filterEpoch: o.epoch ?? this.epoch, reason: o.reason ?? (this.epoch === 0 ? 'start' : 'recovery'), initialInputs, initialControlCursor: o.cursor ?? -1 }, o);
  }

  calibration(id, o = {}) {
    const from = o.from ?? T0;
    const common = {
      calibrationId: id,
      supersedesCalibrationId: o.supersedes ?? null,
      origin: o.origin ?? 'manual_upright',
      effectiveFromMonotonicUs: from,
      writtenMonotonicUs: o.written ?? from,
      upDevice: { x: 0, y: 0.8, z: 0.6 },
      leanAxisDevice: { x: 1, y: 0, z: 0 },
      algorithmVersion: 'calibration-2',
    };
    const range = { fromMonotonicUs: from - 3000000, toMonotonicUs: from - 100000 };
    let fields;
    if (common.origin === 'manual_upright') {
      fields = { ...common, leanAxisSource: 'manual_left_lean', leftLeanConfirmation: { peakLeanMagnitudeDeg: 14.2, durationUs: 2500000, sourceRange: range }, evidence: { kind: 'manual_rest', restDurationUs: 3000000, upSpreadDeg: 0.08, sourceRange: range }, carriedOverFromCalibrationId: null };
    } else if (common.origin === 'auto_straight_ride') {
      fields = { ...common, leanAxisSource: o.axisSource ?? 'unknown', leftLeanConfirmation: null, evidence: { kind: 'auto_straight', accumulatedDurationUs: 30000000, windowCount: 10, minSpeedMps: 8, maxYawRateRadPerS: 0.01, upSpreadDeg: 1.2, sourceRange: range, hintRange: o.hintRange ?? { firstHintSequence: 0, lastHintSequence: 0 } }, carriedOverFromCalibrationId: null };
    } else {
      fields = { ...common, leanAxisSource: 'inherited_from_previous', leftLeanConfirmation: null, evidence: null, carriedOverFromCalibrationId: o.carriedFrom };
    }
    return this.record('lean_calibration', 'lean-estimator', fields, o);
  }

  estimate(o = {}) {
    const angle = o.angle === undefined ? 1.5 : o.angle;
    const calibrationId = o.calibration === undefined ? 'cal-1' : o.calibration;
    const flags = [...(o.flags ?? [])];
    if (angle === null) flags.push('lean_unavailable');
    if (calibrationId === null) flags.push('no_valid_calibration');
    const t = o.t ?? this.now;
    this.now = Math.max(this.now, t);
    return this.record('lean_estimate', 'lean-estimator', {
      measurementMonotonicUs: t,
      computedMonotonicUs: t + 8000,
      leanAngleDeg: angle,
      calibrationId,
      algorithmVersion: 'lean-geometry-2',
      sourceRefs: o.refs ?? [{ sourceId: ACC, firstSequence: 0, lastSequence: 0 }],
      clockMapId: 0,
      filterEpoch: o.epoch ?? this.epoch,
      extremumEligible: o.eligible ?? false,
      motionControlCursor: o.cursor ?? -1,
    }, { flags, boot: o.boot });
  }

  extremum(o = {}) {
    return this.record('lean_extremum', 'lean-estimator', {
      calibrationId: o.calibration ?? 'cal-1',
      side: o.side ?? 'left',
      peakAbsAngleDeg: o.peak,
      eventMonotonicUs: o.eventUs,
      estimateSequence: o.estimateSequence,
      windowStartMonotonicUs: o.windowStart,
      windowEndMonotonicUs: o.windowEnd,
      policyVersion: EXTREMUM_POLICY.policyVersion,
    });
  }

  invalidated(id, at, reason = 'user_cleared') {
    return this.event('calibration_invalidated', { calibrationId: id, invalidatedAtMonotonicUs: at, reason });
  }

  hint(o = {}) {
    return this.record('lean_hint', 'lean-hint', {
      hintKind: 'gps_fix',
      fix: o.fix ?? { deviceBootId: this.boot, measurementMonotonicUs: T0 + (o.i ?? 0) * 1000000, clockVerified: true, speedMps: 12, horizontalAccuracyM: 4, speedAccuracyMps: 0.5, headingDeg: 90, headingAccuracyDeg: 2 },
      gpsRef: o.gpsRef === undefined ? { sourceId: 'android-gnss', sequence: o.i ?? 0 } : o.gpsRef,
      afterInputs: o.after ?? [{ sourceId: ACC, sequence: o.i ?? 0 }],
    });
  }

  autoReset(reason = 'manual_command', after = [{ sourceId: ACC, sequence: 0 }]) {
    return this.event('auto_reference_reset', { reason, afterInputs: after });
  }

  autoState(state, reason, after = [{ sourceId: ACC, sequence: 0 }]) {
    return this.event('auto_reference_state', { state, reason, afterInputs: after });
  }

  estimatorState(state, reason = null) {
    return this.event('estimator_state', { state, reason });
  }

  resumed(reason = 'process_restart', o = {}) {
    return this.event('recording_resumed', { reason, resumedSequences: o.resumedSequences ?? Object.fromEntries([...this.seq.entries()]) }, o);
  }

  edit(index, fn) {
    const record = JSON.parse(this.lines[index]);
    fn(record);
    this.lines[index] = JSON.stringify(record);
    return this;
  }

  text() {
    return `${this.lines.join('\n')}\n`;
  }
}
